"use strict";(self.webpackChunkkiwi_wiki=self.webpackChunkkiwi_wiki||[]).push([["5943"],{16042(i){i.exports=JSON.parse('{"tag":{"label":"Archlinux","permalink":"/en/docs/tags/archlinux","allTagsPath":"/en/docs/tags","count":13,"items":[{"id":"HomeLab/Linux/Archive/ArchInstallScript/w-0026","title":"All-in-One Arch Linux Automated Install Script Guide (arch.sh)","description":"Documents the partitioning, package installation, and chroot workflow of an early custom Arch Linux automated install script (arch.sh), now superseded by the official archinstall tool.","permalink":"/en/docs/HomeLab/Linux/Archive/ArchInstallScript/w-0026"},{"id":"HomeLab/Linux/Archive/ArchInstallScript/w-0028","title":"Arch Linux All-in-One Automated Install Script: Nextcloud Deployment (nextc_arch.sh)","description":"A record of an early shell script that automatically deployed Nextcloud, MariaDB, PHP-FPM, and Nginx inside an Arch Linux chroot (superseded by archinstall and Docker).","permalink":"/en/docs/HomeLab/Linux/Archive/ArchInstallScript/w-0028"},{"id":"HomeLab/Linux/ArchLinux/w-0005","title":"Arch Linux Automated Installation Guide (archinstall)","description":"Covers using the official Arch Linux interactive installation tool archinstall to complete disk partitioning, kernel and desktop environment configuration, and export JSON config files for repeatable deployments.","permalink":"/en/docs/HomeLab/Linux/ArchLinux/w-0005"},{"id":"HomeLab/Linux/Archive/ArchInstallScript/w-0029","title":"Arch Linux Integrated Installation Script: V2Ray Environment Initialization (arch_v2ray.sh)","description":"Analysis of a historically archived Arch Linux chroot automated installation script, covering timezone, netctl network, user, V2Ray, and GRUB configuration.","permalink":"/en/docs/HomeLab/Linux/Archive/ArchInstallScript/w-0029"},{"id":"HomeLab/Linux/ArchLinux/w-0006","title":"Arch Linux KDE Plasma Wayland Setting Up KRDP Remote Desktop Guide","description":"Instructions on removing TigerVNC in Arch Linux\'s KDE Plasma Wayland environment and enabling native RDP remote desktop service via SDDM auto-login and KRDP.","permalink":"/en/docs/HomeLab/Linux/ArchLinux/w-0006"},{"id":"HomeLab/Linux/Archive/ArchInstallScript/w-0030","title":"Integrated Arch Linux Install Script: Dual-NIC Gateway & V2Ray Setup (arch_v2ray_gate.sh)","description":"Documents the legacy Arch Linux dual-NIC gateway installation script arch_v2ray_gate.sh with section-by-section explanations and full source code (superseded by archinstall).","permalink":"/en/docs/HomeLab/Linux/Archive/ArchInstallScript/w-0030"},{"id":"HomeLab/Linux/Archive/ArchInstallScript/w-0025","title":"Integrated Arch Linux Installation Script Architecture Explanation","description":"Documentation of the architectural design and arch-chroot multi-stage execution workflow of an early custom integrated Arch Linux installation script (superseded by archinstall).","permalink":"/en/docs/HomeLab/Linux/Archive/ArchInstallScript/w-0025"},{"id":"HomeLab/Linux/Archive/ArchInstallScript/w-0031","title":"Integrated Arch Linux Installation Script: Minimal Dual-NIC Gateway Setup (arch_v2ray_gate_k.sh)","description":"Documents the legacy Arch Linux dual-NIC gateway installation script arch_v2ray_gate_k.sh, including section-by-section explanations and full source code (discontinued and superseded by archinstall).","permalink":"/en/docs/HomeLab/Linux/Archive/ArchInstallScript/w-0031"},{"id":"HomeLab/Linux/Archive/ArchInstallScript/w-0024","title":"Integrated Arch Linux Installation Script: Preface and Scope","description":"Records the applicable environment and usage of a custom Arch Linux automated installation script, archived after being superseded by the official archinstall.","permalink":"/en/docs/HomeLab/Linux/Archive/ArchInstallScript/w-0024"},{"id":"HomeLab/Linux/Archive/ArchInstallScript/w-0027","title":"Integrated Arch Linux Minimal Installation Script Guide (simple_arch.sh)","description":"Records the architecture and step-by-step analysis of an early custom Arch Linux minimal auto-installation script (simple_arch.sh), now replaced by archinstall and archived.","permalink":"/en/docs/HomeLab/Linux/Archive/ArchInstallScript/w-0027"},{"id":"HomeLab/Linux/ArchLinux/w-0003","title":"systemd-boot Complete Guide and Pacman Hook Automation","description":"Introduce the architecture of systemd-boot in UEFI environments and daily bootctl commands, and explain how to automatically synchronize bootloaders and check kernel configurations via Pacman Hooks.","permalink":"/en/docs/HomeLab/Linux/ArchLinux/w-0003"},{"id":"HomeLab/Linux/ArchLinux/w-0004","title":"The Role and Positioning of Arch Linux in HomeLab","description":"Explains the role of Arch Linux in the HomeLab as a desktop environment (KDE Plasma 6) leveraging the KISS principle and the AUR ecosystem.","permalink":"/en/docs/HomeLab/Linux/ArchLinux/w-0004"},{"id":"HomeLab/Linux/WSL/w-0017","title":"The Role and Purpose of WSL in HomeLab","description":"Explanation of WSL\'s role and primary services (paired with Arch Linux) as a node and VPN springboard connecting back to the HomeLab in a corporate environment.","permalink":"/en/docs/HomeLab/Linux/WSL/w-0017"}],"unlisted":false}}')}}]);